window.__cache={};window.require=function req(name,from=''){let parts=(name.startsWith('.')?from.split('/').slice(0,-1).join('/')+'/'+name:name).split('/'),clean=[];for(const p of parts){if(p==='..')clean.pop();else if(p&&p!=='.')clean.push(p);}let id=clean.join('/');if(!id.endsWith('.js'))id+='.js';if(__cache[id])return __cache[id].exports;if(!__modules[id])throw Error('Missing module '+id);const m=__cache[id]={exports:{}};__modules[id](n=>req(n,id),m,m.exports);return m.exports;};
window.CC_WECHATGAME=false;window.CC_EDITOR=false;window.CC_PREVIEW=false;window.CC_BUILD=true;window.CC_JSB=false;window.CC_DEBUG=false;
